// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    // fuzz parameters: amount to send and a boolean (unused) to ensure at least two fuzz params
    function testFuzz_property(uint256 amount, bool dummy) public {
        // Keep amount within reasonable bounds so vm.deal doesn't overflow and so it fits balances
        amount = bound(amount, 1, 1 ether);

        // deploy a callee that will revert when receiving funds
        Reverter rev = new Reverter();

        // fund the owner (which is address(this) because setUp deploys c from this test contract)
        vm.deal(address(this), amount);

        // call must be from owner (this contract deployed C), so just try calling
        bool ok;
        try c.sendTo(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (one assertion): When owner calls sendTo forwarding ETH to a reverting recipient,
        // the reference implementation always reverts (so ok == false). The mutant that ignores the
        // call result can return ok == true for some inputs — causing this assertion to fail on the mutant.
        assertTrue(!ok);
    }
}

// adversarial callee that ALWAYS reverts on receive/call
contract Reverter {
    fallback() external payable {
        revert("no funds");
    }
    receive() external payable {
        revert("no funds");
    }
}
